const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const inpu = @import("ru-huma-inpu.zig");
test "find by role and label, then click and type incl. non-ASCII" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const aren = rig.aren.allocator(); try rig.go("/support"); const box = (try rig.page.axFind(aren, "textbox", &.{"Message"}, 0)) orelse return error.TestUnexpectedResult; var env = rig.env(); const bpt = try rig.page.center(aren, box); try inpu.click(&env, bpt.x, bpt.y); try inpu.typeText(&env, "Hello xin chào, đây là thử nghiệm"); const sbt = (try rig.page.axFind(aren, "button", &.{"Send"}, 0)) orelse return error.TestUnexpectedResult; const spt = try rig.page.center(aren, sbt); try inpu.click(&env, spt.x, spt.y); const rec = rig.waitRec("btn", 5000) orelse return error.TestUnexpectedResult; try std.testing.expect(std.mem.find(u8, rec, "Hello xin chào, đây là thử nghiệm") != null); }
test "label match ignores case; exact name beats a partial one; unknown label gives null" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const aren = rig.aren.allocator(); try rig.go("/identity/domains/my-profile/api-keys"); try std.testing.expect((try rig.page.axFind(aren, "button", &.{"ADD API KEY"}, 0)) != null); try std.testing.expect((try rig.page.axFind(aren, "button", &.{"no such button"}, 0)) == null); try std.testing.expectEqual(@as(usize, 1), try rig.page.axCount(aren, "button", &.{"add api key"})); }
test "nth match picks the second button with a shared word" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const aren = rig.aren.allocator(); try rig.go("/identity/domains/my-profile/api-keys"); const labs = [_][]const u8{"key"}; const cnt = try rig.page.axCount(aren, "button", &labs); try std.testing.expect(cnt >= 3); const one = (try rig.page.axFind(aren, "button", &labs, 0)).?; const two = (try rig.page.axFind(aren, "button", &labs, 1)).?; try std.testing.expect(one != two); try std.testing.expect((try rig.page.axFind(aren, "button", &labs, cnt)) == null); }
test "key Enter submits the typed text" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const aren = rig.aren.allocator(); try rig.go("/"); const box = (try rig.page.axFind(aren, "textbox", &.{"Search"}, 0)) orelse return error.TestUnexpectedResult; var env = rig.env(); const pnt = try rig.page.center(aren, box); try inpu.click(&env, pnt.x, pnt.y); try inpu.typeText(&env, "api key"); try inpu.pressKey(&env, "Enter"); const rec = rig.waitRec("key", 5000) orelse return error.TestUnexpectedResult; try std.testing.expectEqualStrings("Search=api key", rec); }
test "mouse path ends on the target and scrolling moves the page" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); const aren = rig.aren.allocator(); try rig.go("/"); var env = rig.env(); try inpu.moveTo(&env, 120.0, 80.0); try std.testing.expectEqual(@as(f64, 120.0), rig.page.mx); try std.testing.expectEqual(@as(f64, 80.0), rig.page.my); _ = try rig.page.evalVal(aren, "document.body.style.height='4000px'"); try inpu.scrollBy(&env, 300.0); const ys = rig.page.evalNum(aren, "Math.round(window.scrollY)"); try std.testing.expect(ys > 0); }
